cat > /tmp/dose.py <<'PY'
import workcell,sys
c=lambda *a: workcell.call(*a)
jar=sys.argv[1]; tare={'J1':123.66,'J2':120.16,'J3':122.71}[jar]
for a in [('robot','place','rack'),('robot','pick',jar),('robot','place','platform')]:
 r=c(*a); print(r.text,flush=True)
 if not r.ok: sys.exit(1)
for i in range(110):
 r=c('scale','read')
 if not r.ok: print(r.text); sys.exit(1)
 net=round(r.data['gross_g']-tare,2); gap=round(250-net,2)
 if i%3==0 or gap<3: print(jar,'net',net,'gap',gap,flush=True)
 if 249.95 <= net <= 250.12:
  r=c('checkweigher','check'); print(r.text,flush=True)
  print(c('station','status').text,flush=True)
  sys.exit(0 if r.ok else 1)
 if net>250.20:
  a=('robot','remove')
 elif gap>65:
  a=('robot','dose','bulk')
 elif gap>13:
  a=('robot','dose','coarse')
 elif gap>2.4:
  a=('robot','dose','fine')
 else:
  a=('robot','dose','micro')
 r=c(*a)
 if not r.ok: print('ERROR:',r.text,flush=True);sys.exit(1)
 if i%3==0 or gap<3: print(r.text,flush=True)
print('no convergence',c('station','status').text)
sys.exit(1)
